2720	                    if (r.app != null) {
2721	                        updateServiceForegroundLocked(psr, true);
2722	                    }
2723	                    getServiceMapLocked(r.userId).ensureNotStartingBackgroundLocked(r);
2724	                    mAm.notifyPackageUse(r.serviceInfo.packageName,
2725	                            PackageManager.NOTIFY_PACKAGE_USE_FOREGROUND_SERVICE);
2726	
2727	                    if (CompatChanges.isChangeEnabled(FGS_INTRODUCE_TIME_LIMITS, r.appInfo.uid)
2728	                            && android.app.Flags.introduceNewServiceOntimeoutCallback()) {
2729	                        maybeUpdateFgsTrackingLocked(r, previousFgsType);
2730	                    }
2731	                } else {
2732	                    if (DEBUG_FOREGROUND_SERVICE) {
2733	                        Slog.d(TAG, "Suppressing startForeground() for FAS " + r);
2734	                    }
2735	                }
2736	            } finally {
2737	                if (stopProcStatsOp) {
2738	                    // We got through to this point with it actively being started foreground,
2739	                    // and never decided we wanted to keep it like that, so drop it.
2740	                    synchronized (mAm.mProcessStats.mLock) {
2741	                        final ServiceState stracker = r.getTracker();
2742	                        if (stracker != null) {
2743	                            stracker.setForeground(false, mAm.mProcessStats.getMemFactorLocked(),
2744	                                    SystemClock.uptimeMillis());
2745	                        }
2746	                    }
2747	                }
2748	                if (alreadyStartedOp) {
2749	                    // If we had previously done a start op for direct foreground start,
2750	                    // we have cleared the flag so can now drop it.
2751	                    mAm.mAppOpsService.finishOperation(
2752	                            AppOpsManager.getToken(mAm.mAppOpsService),
2753	                            AppOpsManager.OP_START_FOREGROUND, r.appInfo.uid, r.packageName,
2754	                            null);
2755	                }
2756	            }
2757	        } else {
2758	            if (r.isForeground) {
2759	                traceInstant("stopForeground(): ", r);
2760	                final ServiceMap smap = getServiceMapLocked(r.userId);
2761	                if (smap != null) {
2762	                    decActiveForegroundAppLocked(smap, r);
2763	                }
2764	
2765	                maybeStopShortFgsTimeoutLocked(r);
2766	                maybeStopFgsTimeoutLocked(r);
2767	
2768	                // Adjust notification handling before setting isForeground to false, because
2769	                // that state is relevant to the notification policy side.
2770	                // Leave the time-to-display as already set: re-entering foreground mode will
2771	                // only resume the previous quiet timeout, or will display immediately if the
2772	                // deferral period had already passed.
2773	                if ((flags & Service.STOP_FOREGROUND_REMOVE) != 0) {
2774	                    cancelForegroundNotificationLocked(r);
2775	                    r.foregroundId = 0;
2776	                    r.foregroundNoti = null;
2777	                } else if (r.appInfo.targetSdkVersion >= Build.VERSION_CODES.LOLLIPOP) {
2778	                    // if it's been deferred, force to visibility
2779	                    if (!r.mFgsNotificationShown) {
2780	                        r.postNotification(false);
2781	                    }
2782	                    dropFgsNotificationStateLocked(r);
2783	                    if ((flags & Service.STOP_FOREGROUND_DETACH) != 0) {
2784	                        r.foregroundId = 0;
2785	                        r.foregroundNoti = null;
2786	                    }
2787	                }
2788	
2789	                mAm.mProcessStateController.setIsForegroundService(r, false);
2790	                r.mFgsExitTime = SystemClock.uptimeMillis();
2791	                synchronized (mAm.mProcessStats.mLock) {
2792	                    final ServiceState stracker = r.getTracker();
2793	                    if (stracker != null) {
2794	                        stracker.setForeground(false, mAm.mProcessStats.getMemFactorLocked(),
2795	                                SystemClock.uptimeMillis());
2796	                    }
2797	                }
2798	                mAm.mAppOpsService.finishOperation(
2799	                        AppOpsManager.getToken(mAm.mAppOpsService),
2800	                        AppOpsManager.OP_START_FOREGROUND, r.appInfo.uid, r.packageName, null);
2801	                unregisterAppOpCallbackLocked(r);
2802	                logFGSStateChangeLocked(r,
2803	                        FOREGROUND_SERVICE_STATE_CHANGED__STATE__EXIT,
2804	                        r.mFgsExitTime > r.mFgsEnterTime
2805	                                ? (int) (r.mFgsExitTime - r.mFgsEnterTime) : 0,
2806	                        FGS_STOP_REASON_STOP_FOREGROUND,
2807	                        FGS_TYPE_POLICY_CHECK_UNKNOWN,
2808	                        FOREGROUND_SERVICE_STATE_CHANGED__FGS_START_API__FGSSTARTAPI_NA,
2809	                        false /* fgsRestrictionRecalculated */
2810	                );
2811	
2812	                synchronized (mFGSLogger) {
2813	                    mFGSLogger.logForegroundServiceStop(r.appInfo.uid, r);
2814	                }
2815	                // foregroundServiceType is used in logFGSStateChangeLocked(), so we can't clear it
2816	                // earlier.
2817	                r.foregroundServiceType = 0;
2818	                r.mFgsNotificationWasDeferred = false;
2819	                r.systemRequestedFgToBg = systemRequestedTransition;
2820	                signalForegroundServiceObserversLocked(r);
2821	                resetFgsRestrictionLocked(r);
2822	                mAm.updateForegroundServiceUsageStats(r.name, r.userId, false);
2823	                if (r.app != null) {
2824	                    mAm.updateLruProcessLocked(r.app, false, null);
2825	                    updateServiceForegroundLocked(r.app.mServices, true);
2826	                }
2827	                updateNumForegroundServicesLocked();
2828	            }
2829	        }
2830	    }
