2854	    /**
2855	     * Validate if the given service can start a foreground service with given type.
2856	     *
2857	     * @return A pair, where the first parameter is the result code and second is the exception
2858	     *         object if it fails to start a foreground service with given type.
2859	     */
2860	    @NonNull
2861	    private Pair<Integer, RuntimeException> validateForegroundServiceType(ServiceRecord r,
2862	            @ForegroundServiceType int type,
2863	            @ForegroundServiceType int defaultToType,
2864	            @ForegroundServiceType int startType) {
2865	        final ForegroundServiceTypePolicy policy = ForegroundServiceTypePolicy.getDefaultPolicy();
2866	        final ForegroundServiceTypePolicyInfo policyInfo =
2867	                policy.getForegroundServiceTypePolicyInfo(type, defaultToType);
2868	        final @ForegroundServicePolicyCheckCode int code = policy.checkForegroundServiceTypePolicy(
2869	                mAm.mContext, r.packageName, r.app.uid, r.app.getPid(),
2870	                r.isFgsAllowedWiu_forStart(), policyInfo);
2871	        RuntimeException exception = null;
2872	        switch (code) {
2873	            case FGS_TYPE_POLICY_CHECK_DEPRECATED: {
2874	                final String msg = "Starting FGS with type "
2875	                        + ServiceInfo.foregroundServiceTypeToLabel(type)
2876	                        + " code=" + code
2877	                        + " callerApp=" + r.app
2878	                        + " targetSDK=" + r.app.info.targetSdkVersion;
2879	                Slog.wtfQuiet(TAG, msg);
2880	                Slog.w(TAG, msg);
2881	            } break;
2882	            case FGS_TYPE_POLICY_CHECK_DISABLED: {
2883	                if (startType == FOREGROUND_SERVICE_TYPE_MANIFEST
2884	                        && type == FOREGROUND_SERVICE_TYPE_NONE) {
2885	                    exception = new MissingForegroundServiceTypeException(
2886	                            "Starting FGS without a type "
2887	                            + " callerApp=" + r.app
2888	                            + " targetSDK=" + r.app.info.targetSdkVersion);
2889	                } else {
2890	                    exception = new InvalidForegroundServiceTypeException(
2891	                            "Starting FGS with type "
2892	                            + ServiceInfo.foregroundServiceTypeToLabel(type)
2893	                            + " callerApp=" + r.app
2894	                            + " targetSDK=" + r.app.info.targetSdkVersion
2895	                            + " has been prohibited");
2896	                }
2897	            } break;
2898	            case FGS_TYPE_POLICY_CHECK_PERMISSION_DENIED_PERMISSIVE: {
2899	                final String msg = "Starting FGS with type "
2900	                        + ServiceInfo.foregroundServiceTypeToLabel(type)
2901	                        + " code=" + code
2902	                        + " callerApp=" + r.app
2903	                        + " targetSDK=" + r.app.info.targetSdkVersion
2904	                        + " requiredPermissions=" + policyInfo.toPermissionString()
2905	                        + (policyInfo.hasForegroundOnlyPermission()
2906	                        ? " and the app must be in the eligible state/exemptions"
2907	                        + " to access the foreground only permission" : "");
2908	                Slog.wtfQuiet(TAG, msg);
2909	                Slog.w(TAG, msg);
2910	            } break;
2911	            case FGS_TYPE_POLICY_CHECK_PERMISSION_DENIED_ENFORCED: {
2912	                exception = new SecurityException("Starting FGS with type "
2913	                        + ServiceInfo.foregroundServiceTypeToLabel(type)
2914	                        + " callerApp=" + r.app
2915	                        + " targetSDK=" + r.app.info.targetSdkVersion
2916	                        + " requires permissions: "
2917	                        + policyInfo.toPermissionString()
2918	                        + (policyInfo.hasForegroundOnlyPermission()
2919	                        ? " and the app must be in the eligible state/exemptions"
2920	                        + " to access the foreground only permission" : ""));
2921	            } break;
2922	            case FGS_TYPE_POLICY_CHECK_OK:
2923	            default:
2924	                break;
2925	        }
2926	        return Pair.create(code, exception);
2927	    }
