3023	    ServiceNotificationPolicy applyForegroundServiceNotificationLocked(Notification notification,
3024	            final String tag, final int id, final String pkg, final int userId) {
3025	        // By nature of the FGS API, all FGS notifications have a null tag
3026	        if (tag != null) {
3027	            return ServiceNotificationPolicy.NOT_FOREGROUND_SERVICE;
3028	        }
3029	
3030	        if (DEBUG_FOREGROUND_SERVICE) {
3031	            Slog.d(TAG_SERVICE, "Evaluating FGS policy for id=" + id
3032	                    + " pkg=" + pkg + " not=" + notification);
3033	        }
3034	
3035	        // Is there an FGS using this notification?
3036	        final ServiceMap smap = mServiceMap.get(userId);
3037	        if (smap == null) {
3038	            // No services in this user at all
3039	            return ServiceNotificationPolicy.NOT_FOREGROUND_SERVICE;
3040	        }
3041	
3042	        for (int i = 0; i < smap.mServicesByInstanceName.size(); i++) {
3043	            final ServiceRecord sr = smap.mServicesByInstanceName.valueAt(i);
3044	            if (!sr.isForeground
3045	                    || id != sr.foregroundId
3046	                    || !pkg.equals(sr.appInfo.packageName)) {
3047	                // Not this one; keep looking
3048	                continue;
3049	            }
3050	
3051	            // Found; it is associated with an FGS.  Make sure that it's flagged:
3052	            // it may have entered the bookkeeping outside of Service-related
3053	            // APIs.  We also make sure to take this latest Notification as
3054	            // the content to be shown (immediately or eventually).
3055	            if (DEBUG_FOREGROUND_SERVICE) {
3056	                Slog.d(TAG_SERVICE, "   FOUND: notification is for " + sr);
3057	            }
3058	            notification.flags |= Notification.FLAG_FOREGROUND_SERVICE;
3059	            sr.foregroundNoti = notification;
3060	
3061	            // ...and determine immediate vs deferred display policy for it
3062	            final boolean showNow = shouldShowFgsNotificationLocked(sr);
3063	            if (showNow) {
3064	                if (DEBUG_FOREGROUND_SERVICE) {
3065	                    Slog.d(TAG_SERVICE, "   Showing immediately due to policy");
3066	                }
3067	                sr.mFgsNotificationDeferred = false;
3068	                return ServiceNotificationPolicy.SHOW_IMMEDIATELY;
3069	            }
3070	
3071	            // Deferring - kick off the timer if necessary, and tell the caller
3072	            // that it's to be shown only if it's an update to already-
3073	            // visible content (e.g. if it's an FGS adopting a
3074	            // previously-posted Notification).
3075	            if (DEBUG_FOREGROUND_SERVICE) {
3076	                Slog.d(TAG_SERVICE, "   Deferring / update-only");
3077	            }
3078	            startFgsDeferralTimerLocked(sr);
3079	            return ServiceNotificationPolicy.UPDATE_ONLY;
3080	        }
3081	
3082	        // None of the services in this user are FGSs
3083	        return ServiceNotificationPolicy.NOT_FOREGROUND_SERVICE;
3084	    }
