1588	    private @Nullable String getShortProcessNameForStats(int uid, String processName) {
1589	        final String[] packages = mAm.mContext.getPackageManager().getPackagesForUid(uid);
1590	        if (packages != null && packages.length == 1) {
1591	            // Not the shared UID case, let's see if the package name equals to the process name.
1592	            if (TextUtils.equals(packages[0], processName)) {
1593	                // same name, just return null here.
1594	                return null;
1595	            } else if (processName != null && processName.startsWith(packages[0])) {
1596	                // return the suffix of the process name
1597	                return processName.substring(packages[0].length());
1598	            }
1599	        }
1600	        // return the full process name.
1601	        return processName;
1602	    }
